import tempfile, shutil, json, os
from threshold_wallet.store import WalletStore, RecoveryError
from threshold_wallet.service import WalletService, ServiceError
KEY_A="aa"*32; KEY_B="bb"*32; KEY_C="cc"*32
def fresh():
    d=tempfile.mkdtemp(); store=WalletStore(d)
    s=WalletService(store); s.create_wallet("w1",2)
    s.put_dkg_nodes("w1",{"n1":{"key":KEY_A,"state":"up"},"n2":{"key":KEY_B,"state":"down"}})
    return d,store,s
def rewrite(d,mut):
    p=os.path.join(d,"audit","w1.json"); log=json.load(open(p)); mut(log); json.dump(log,open(p,"w"))

# outer key reorder
d,store,s=fresh()
def m1(log):
    for e in log["events"]:
        if e["type"]=="node_state":
            # move type first
            items=list(e.items()); items=[items[-1]]+items[:-1]
            e.clear(); e.update(items)
rewrite(d,m1)
try: WalletService(WalletStore(d)); print("FAIL outer reorder accepted")
except RecoveryError: print("outer reorder -> RecoveryError OK")
shutil.rmtree(d)

# entry key reorder (state,key)
d,store,s=fresh()
def m2(log):
    for e in log["events"]:
        if e["type"]=="node_state":
            for nid,v in e["details"]["nodes"].items():
                e["details"]["nodes"][nid]={"state":v["state"],"key":v["key"]}
rewrite(d,m2)
try: WalletService(WalletStore(d)); print("FAIL entry reorder accepted")
except RecoveryError: print("entry reorder -> RecoveryError OK")
shutil.rmtree(d)

# node id descending
d,store,s=fresh()
def m3(log):
    for e in log["events"]:
        if e["type"]=="node_state":
            nodes=e["details"]["nodes"]
            e["details"]["nodes"]={k:nodes[k] for k in sorted(nodes,reverse=True)}
rewrite(d,m3)
try: WalletService(WalletStore(d)); print("FAIL id desc accepted")
except RecoveryError: print("id desc -> RecoveryError OK")
shutil.rmtree(d)

# details extra key
