        if current_round["state"] not in ("commit", "share"):
            raise RecoveryError(
                f"wallet {wallet_id!r} node_rejoined {rejoin_id!r} round "
                "is not in the commit/share stage"
            )
        node_ids = [n for n, _ in current_round["nodes"]]
        if node in node_ids:
